const ctl = new AbortController();
const t = setTimeout(() => ctl.abort(), 2000);   // 2초 타임아웃
try {
  const res = await fetch(url, { signal: ctl.signal });
  return res;
} finally {
  clearTimeout(t);
}
// ★ 기본값이 무한대인 클라이언트가 많다 — HTTP·DB 드라이버·외부 SDK
//   전부 명시적 타임아웃을 확인·설정하라

for (let i = 0; i < 3; i++) {           // 횟수 제한(무한 X)
  try { return await call(); }
  catch (e) {
    if (!isRetryable(e)) throw e;         // 재시도 가능한 오류만(4xx 는 X)
    const base = 1000 * 2 ** i;           // 지수 백오프: 1s·2s·4s
    const jitter = Math.random() * base;  // 지터: 몰림 방지
    await sleep(base + jitter);
  }
}
// + 재시도는 멱등해야 안전(pay-idem) · 과부하면 재시도가 불에 기름

const [order, recs] = await Promise.allSettled([
  getOrder(id),            // 핵심 — 이건 정말 필요
  getRecommendations(id),  // 부가 — 실패해도 됨
]);
if (order.status === 'rejected') throw order.reason;  // 핵심 실패는 진짜 실패
return {
  order: order.value,
  recs: recs.status === 'fulfilled' ? recs.value : [],  // 부가 실패 → 빈 값
};
// Promise.all 이면 recs 하나 실패에 전부 실패 → 페이지 안 뜸
